registerRefData('nsw-cond-n-6969',{"id":6969,"pan":null,"ref":"DA/673/2011","address":"1-20 Village Way Canton Beach","description":"Additions to an existing Aged Care Facility","outcome":null,"outcome_raw":"","outcome_source":"planning_panels","determined":null,"notice_url":"https://apps.planningportal.nsw.gov.au/prweb/PRRestService/DocMgmt/v1/PublicDocuments/DATA-WORKATTACH-FILE PEC-DPE-EP-WORK PPS-2011HCC036!20190614T182206.623 GMT","sha256":"8b959d92e94e726ac0be75446bee7f6a55ad49f61ae827d8803314aeb2920a6d","pages":21,"layout":"numbered","n":91,"fetched_at":"2026-08-17T01:20:28+00:00","file":"n/6969.js","source_page":"https://www.planningportal.nsw.gov.au/planning-panel/additions-existing-aged-care-facility","lga":"CENTRAL COAST","conditions":[{"label":"1","code":null,"number":"1","title":"The meeting commenced at 11.50 am","text":"The Chair welcomed everyone to the meeting of the Panel.\n2. Declarations of Interest - Nil\n3. Business Items\nITEM 1 - 2011HCC036 - Wyong Council, DA/673/2011, Additions to an existing Aged\nCare Facility, 1-20 Village Way, Canton Beach\n4. Public Submission -\nAdam Byrnes (Town Planner for the Applicant) addressed the Panel in favour of the item.\n5. The Panel’s Decision\n2011HCC036 - Wyong Council, DA/673/2011, Additions to an existing Aged Care Facility,\n1-20 Village Way, Canton Beach\nMoved by Cr Eaton Seconded by Bob McCotter\nRECOMMENDATION\n1 The Joint Regional Planning Panel grant consent t o DA/673/2011, subject to the conditions in\nthe report to the Joint Regional Planning Panel on the 29 March 2012 as amended at the\nmeeting.","stage":"unassigned","stage_basis":"unassigned","page":1},{"label":"2","code":null,"number":"2","title":"","text":"That the Joint Regional Planning Panel commends a n initiative that the APZ shown in purple\nto the west of the proposed EEC restoration area shown on the plan on Page 26 of Council’s\nreport being revegetated with EEC species, provided this is acceptable to RFS and LPI.\nNOTE: The following conditions, outlined below in yellow, were amended during the meeting of the\nJoint Regional Planning Panel on the 29 March 2012\nMOTION CARRIED\nThe meeting concluded at 12.50 pm.\nJason Perica\nActing Chair\nHunter & Central Coast\nJoint Regional Planning Panel\nDate: 14 April 2012\nDRAFT CONDITIONS OF CONSENT\nDate: 16 February 2012\nResponsible Officer: Jenny Webb\nLocation: Lakefront Village, 1-20 Village Way, CANTON BEACH NSW\n2263\nLot 496 DP 755266, Lot 600 DP 728966, Lot 602 DP 728967\nOwner: Christadelphian Homes Ltd\nApplicant: Christadelphian Homes Ltd\nDate Of Application: 4 August 2011\nApplication No: DA/673/2011\nProposed Development: Additions to an existing Aged Care Facility comprising a\nproposed Residential Care Facility containing 95 beds and\nancillary works\nLand Area: 49320.00\nPROPOSED CONDITIONS\nApproved Plans\n1 The development is to be undertaken in accordance with the approved development plans\nlisted below and supporting documentation, except as modified by any conditions of consent.\nand any amendments made by Counci l in red on t he approved plans :\nTitle Drawing\nNo. Revision Date Drawn By\nApproved and Proposed\nSite Plans\n08-225 A01 C 7/11 Martin\nO’Toole\nArchitects\nGround Floor Plan 08-225 A02 C 7/11 Martin\nO’Toole\nArchitects\nFirst Floor Plan 08-225 A03 C 7/11 Martin\nO’Toole\nArchitects\nRoof Plan 08-225 A04 C 7/11 Martin\nO’Toole\nArchitects\nSet-Out Plan 08-225 A05 C 7/11 Martin\nO’Toole\nArchitects\nElevations and Sections 08-225 A06 C 7/11 Martin\nO’Toole\nArchitects\nCarparking Plans 08-225 A07 C 7/11 Martin\nO’Toole\nArchitects\nPlan of Existing Tree 08-225 A08 C 7/11 Martin\nO’Toole\nArchitects\nContour and Detail Plan 9898K A 26/7/11 Rolls &\nAssociates\nSurveyors\nConcept Stormwater Plan 89024411-\nC01 and\nC02\n2 29/7/11 Cardno\n(NSW/ACT)\nPty Ltd\nConcept Erosion and\nSedimentation Control Plan\n89024411-\nC03\n2 29/7/11 Cardno\n(NSW/ACT)\nPty Ltd\nLandscape Plan 11.6.1\nSheets 1\nand 2\nB 13/7/11 Wallman\nPartners\nPty Ltd\nFlora and Fauna\nAssessment\nA10008F2 - July 2011 Travers\nBushfire\nand\nEcology\nVegetation Management\nPlan\nA10008 V - 28 July\n2011\nTravers\nBushfire\nand\nEcology\nPreliminary Acid Sulphate\nSoil Investigation and Acid\nSulphate Soil Management\nPlan\n90215 - 23 July\n2011\nBarker\nHarle\nConsulting\nEngineers\nBushfire Hazard\nAssessment Report\n80316C - 26 July\n2011\nBuilding\nCode &\nBushfire\nHazard\nSolutions\nPty Limited\nAccess Report AR1106/053\nC\n- 14 July\n2011\nAJA\nAccess\nConsultants\nTraffic Impact Assessment 2929 - July 2011 Christopher\nHallam &\nAssociates\nPty Ltd\nBuilding Code of Australia\nCompliance Report\n- B 28 July\n2011\nTom\nMiskovich\n&\nAssociates\nConcept Water Cycle\nManagement Plan\n8902 44.11 3 July 2011 Cardno\n(NSW/ACT)\nPty Ltd\nAdd list of relevant consultant reports\nCertificates - Application and Approval\n2 A Construction Certificate is to be issued by the Principal Certifying Authority prior to\ncommencement of any construction works. The application for this Certificate is to satisfy all\nof the requirements of the Environmental Planning and Assessment Regulation 2000.","stage":"unassigned","stage_basis":"unassigned","page":2},{"label":"3","code":null,"number":"3","title":"","text":"Prior to the occupation or use of the building/st ructure, an application for an Occupation\nCertificate for the development must be submitted to and approved by the Principal Certifying\nAuthority.","stage":"unassigned","stage_basis":"unassigned","page":4},{"label":"4","code":null,"number":"4","title":"","text":"Where conditions of this consent require approval from Council under the Roads Act 1993,\nLocal Government Act 1993 or Water Management Act 2000, a completed Application for\nCivil Works and Subdivision Works must be lodged with Council and be accompanied by\ndetailed design drawings and supporting information. Upon submission to Council, fees and\ncharges will be calculated in accordance with Council’s Management Plan. The fees and\ncharges must be paid prior to Council commencing the design assessment.","stage":"unassigned","stage_basis":"unassigned","page":5},{"label":"5","code":null,"number":"5","title":"","text":"The proposed development has been assessed agains t the provisions of Planning for\nBushfire Protection 2006 (NSW) and has been determined as having a Bushfire Attack Level\n(BAL) of 12.5. Prior to the issue of a Construction Certificate, construction details\ndemonstrating compliance with AS3959-2009 - Construction in Bushfire Prone Areas and\nadditional measures contained in Section A3.7 Addendum Appendix 3 of the PBP Guidelines\nfor the nominated BAL must be provided for the approval of the Accredited Certifier.\nContribution Payment Requirements","stage":"before_cc","stage_basis":"heading","page":5},{"label":"6","code":null,"number":"6","title":"","text":"Prior to the issue of a Construction Certificate, the payment to Council of contributions (as\ncontained in the attached Schedule, unless the appl icant can demonstrate that such a\ncontribution is not required by the Ministerial Dir ection under S94E of the Environmental\nPlanning and Assessment Act, 1979, (dated 14 Septem ber 2007) under Section 94 of the\nEnvironmental Planning and Assessment Act 1979 and Council’s Section 94 and Section\n94A Contribution Plan. Council’s contributions are adjusted on the first day of February,\nMay, August and November. The amount of the contrib utions will be adjusted to the amount\napplicable at the date of payment.\nDust Control Requirements","stage":"before_cc","stage_basis":"heading","page":5},{"label":"7","code":null,"number":"7","title":"","text":"Prior to the issue of a Construction Certificate, suitable details must be provided for the\napproval of the Accredited Certifier of an appropriate system to control dust emissions from\nthe site during construction works. The approved method of controlling dust emissions from\nthe site is to be implemented and be maintained for the duration of construction works on the\nsite.\nEcology/Tree Requirements","stage":"before_cc","stage_basis":"heading","page":5},{"label":"8","code":null,"number":"8","title":"","text":"Prior to the issue of any Construction Certificat e, trees and native vegetation proposed for\nretention and those approved for removal must be clearly identified on all the final\nengineering and landscaping plans. All fenced tree protection areas must be clearly marked\nas \"No Go Area\" on all plans. The location of any threatened species, endangered\npopulations or ecological communities must also be marked on all plans.\nErosion and Sediment Control - Design Requirements","stage":"before_cc","stage_basis":"heading","page":5},{"label":"9","code":null,"number":"9","title":"","text":"Prior to the issue of a Construction Certificate, design drawings for the control of soil erosion\non the site and the prevention of silt discharge into drainage systems and waterways must be\nprovided for the approval of the Accredited Certifier. Required design drawings must include\nall major stages of construction and sequences of work together with treatments necessary\nat each of these stages. The design drawings must be prepared in accordance with the\nLandcom publication ‘ Soils and Construction - Managing Urban Stormwater ’ (Blue Book) .\nLandscaping Design Requirements","stage":"before_cc","stage_basis":"heading","page":6},{"label":"10","code":null,"number":"10","title":"","text":"Prior to the issue of a Construction Certificate , landscape design drawings, prepared by an\napproved consultant, must be provided for the approval of the Accredited Certifier. Such\nlandscape design plans must be prepared in accordance with Council’s Landscape Policy L1\nfor a Category 3 development and clearly identify the replacement of the 57 trees proposed\nto be removed from the site.\nRoadworks - Design Requirements","stage":"before_cc","stage_basis":"heading","page":6},{"label":"11","code":null,"number":"11","title":"","text":"The submission to Council of Civil Works design drawings and specifications detailing the\nfollowing design requirements for the full length of Village Way:\n• Kerb and guttering or an approved alternative suit able to Council for the full street\nfrontage of the development on both sides of Village Way. The application of Water\nSensitive Urban Design may be included to satisfy this requirement.\n• Minimum 6.5m road pavement construction adjoining the proposed kerb and guttering.\nThis condition shall require a widening of the existing pavement to 6.5m or the\nreconstruction of the existing pavement to 6.5m wide to match proposed kerb and\nguttering.\n• Street stormwater drainage systems to accommodate the approved kerb and\nguttering/swale and road pavement design and construction.\n• Street lighting in accordance with AS/NZS 1158 and AS 4282-1997.\n• Pavement marking and signage.\n• Pavement design catering for 3x10 5 equivalent standard axles (a local access street).\nThis condition shall require the upgrade of the existing pavement or demonstration of\nit’s suitability to meet the required loadings.\n• Vehicle access crossing(s).\n• Any associated works to ensure satisfactory transi tions to existing infrastructure\nRequired design drawings and required engineering details are to be prepared in accordance\nwith Council's Development Control Plan 2005, Chapter 67 - Engineering Requirements for\nDevelopment and must be approved by Council as the Roads Authority (including any\nrefinements to the above being approved by Council) prior to the issue of a Construction\nCertificate.","stage":"before_cc","stage_basis":"heading","page":6},{"label":"12","code":null,"number":"12","title":"","text":"The submission to Council of Civil Works design drawings and specifications detailing the\nprovision of a basic right and basic left intersection as identified in Austroads - Guide to\nRoad Design Part 4A for the intersection of Village Way and Evans Road. The design shall\ninclude the following design requirements:\n• Kerb and guttering or an approved alternative suit able to Council for the length of the\nrequired intersection treatment including transitional areas on the western side of\nEvans Road.\n• The provision of road pavement construction for th e full area of the required\nintersection treatment. The existing pavement shall be widened to accommodate the\nproposed intersection treatment or the reconstruction of the existing pavement to\nmatch the proposed design.\n• stormwater drainage systems including longitudina l drainage to accommodate road\nwidening and extension of the transverse piped drainage culverts immediately south of\nthe intersection to provide for the intersection design.\n• Street lighting in accordance with AS/NZS 1158 and AS 4282-1997.\n• Pavement marking and signage.\n• Pavement design catering for 2x10 6 equivalent standard axles(distributor / bus routes).\nThis condition shall require the upgrade of the existing pavement or demonstration of\nit’s suitability to meet the required loadings.\n• Any associated works to ensure satisfactory transi tions to existing infrastructure.\n• The removal of the bus stop on the eastern side of the intersection of Village Way and\nEvans Road. This will require the agreement of Council and the relevant local bus\ncompanies. Alternatively the bus stop shall be moved clear of the proposed intersection\nand upgraded to current standards in accordance with the requirements of the\nAustralian Human Rights Commission - Accessible Bus Stop Guidelines and the\nDepartment of Transport.\n• The upgrading of the bus stop to the north-western side of the intersection of Village\nWay and Evans Road in accordance with the requirements of the Australian Human\nRights Commission - Accessible Bus Stop Guidelines and the Department of Transport\nRequired design drawings are to be prepared in accordance with Council's Development\nControl Plan 2005, Chapter 67 - Engineering Requirements for Development and must be\napproved by Council as the Roads Authority (including any refinements to the above being\napproved by Council) prior to the issue of a Construction Certificate.","stage":"before_cc","stage_basis":"heading","page":7},{"label":"13","code":null,"number":"13","title":"The provision of vehicular access crossings in a ccordance with Council's Development","text":"Control Plan 2005, Chapter 67 - Engineering Requirements for Development . Design\ndrawings must be approved by Council as the Roads Authority prior to the issue of a\nConstruction Certificate and shall require the retention of the existing trees within Village\nWay included in the designs. The designs shall comply with AS/NZS2890.2 where heavy\nvehicles are expected to access.","stage":"before_cc","stage_basis":"heading","page":7},{"label":"14","code":null,"number":"14","title":"","text":"The provision of a concrete footpath 1.5 metres wide for the full street frontage(s) of the\ndevelopment at the sole cost of the developer. The proposed concrete footpaving is to\nconnect to the existing footpaving in Evans Road and shall consider existing established\ntrees in Village Way as part of the design. The concrete paving is to be 100mm thick with\nSL72 reinforcement and is to be constructed on 75mm compacted road base and on\ncompacted sub grade. All other details are to be in accordance with Council's Development\nControl Plan 2005, Chapter 67 - Engineering Requirements for Development . The design\ndrawings must be approved by Council as the Roads Authority prior to issue of a\nConstruction Certificate.","stage":"before_cc","stage_basis":"heading","page":7},{"label":"15","code":null,"number":"15","title":"","text":"The submission to Council of road signage and pa vement marking design drawings\nidentifying parking restrictions, accesses and traffic management facilities to Council\nfor\napproval by the Local Traffic Committee prior to issue of the Construction Certificate.","stage":"before_cc","stage_basis":"heading","page":8},{"label":"16","code":null,"number":"16","title":"","text":"Prior to the commencement of detailed design wor ks within any public road, contact should\nbe made with the National Community Service “Dial before you Dig” on 1100 regarding the\nlocation of underground services in order to prevent injury, personal liability and even death.\nEnquiries should provide the property details and the nearest cross street/road.\nStormwater Drainage - Design Requirements","stage":"before_cc","stage_basis":"heading","page":8},{"label":"17","code":null,"number":"17","title":"","text":"The provision of a stormwater system with water quality control facilities required to treat\nstormwater runoff from the development in accordance with Council's Development Control\nPlan No 67 - Engineering Requirements for Development, AS/NZS3500 and Australian\nRunoff Quality - A guide to water sensitive urban d esign. The design shall address the\nstormwater requirements related to the adjacent freshwater wetland in regard to wetting and\ndrying cycles in accordance with Council’s requirements and technical guides. The proposed\ndesign shall consider the total water quality, quantity and flow discharge rates from the\ndevelopment site. The design shall include:-\n• Plans generally in accordance with Plans submitted by Cardno No 89024411-C01 Rev2,\nand No89024411-C02 Rev2.\n• The design shall generally be in accordance with t he reports by Cardno - Concept Water\nCycle Management Plan dated July 2011 and the Hydraulic Design Brief Dated June 2011.\n• All drainage works including swales must be entire ly contained within the development site\nor be covered by appropriate easements.\n• Water quality for storm events up to the 1% AEP st orm event are to meet the water quality\nrequirements of Australian Runoff Quality - A guide to water sensitive urban design\n• Preservation of the 30 day low flow duration frequ ency curve for the dry season (October to\nJanuary)\n• Preservation of the low flows spells frequency cur ve for the dry season (October to\nJanuary)\n• Preservation of the pre development 30 day high fl ow duration frequency curve for all\nmonths\n• Modelling and calculations to demonstrate water qu ality and quantity and flow discharge\nrate outcomes.\n• Stormwater tanks reuse system with a total minimum volume of 60,000 litres. Reuse tanks\nare to be fitted to toilet and external uses.\n• The required stormwater reuse quantity is to be co nsidered in all drainage system\nmodelling for quantity, flow discharge rate, quality and identified flow and spell frequencies.\nWhere it is identified as necessary to adjust stormwater reuse quantities to meet\nenvironmental flows from the site, the reuse amount shall be adjusted accordingly.\n• Stormwater harvesting shall be in accordance with the requirements of the Australian Water\nQuality Management Strategy - Australian Guidelines for Water Recycling: Managing\nHealth and Environmental Risks - Stormwater Harvest ing and Reuse.\n• Overland flow paths for events greater than the de sign storm event are to be suitably\nstabilised in accordance with Council’s Development Control Plan 2005 Chapter 67 and\nLandcom’s “Managing Urban Stormwater - Soil and Con struction” (the Blue Book)\n• All stormwater outlets including existing outlets are to ensure flows are dispersed prior to\nexiting the site. This shall require the installation of level spreader and dissipater device at\nall stormwater outlets including existing stormwater outlets.\nAdjustment to the existing water quantity, quality and flow duration devices within the site will\nbe necessary to satisfy the above requirements. All supporting calculations and modelling must\nbe prepared and certified by a suitably qualified engineer. Design plans and all supporting\ncalculations and modelling must be approved by the Accredited Certifier prior to issue of the\nConstruction Certificate for these works.","stage":"before_cc","stage_basis":"heading","page":8},{"label":"18","code":null,"number":"18","title":"","text":"Stormwater drainage works external to the site a nd / or discharging into a public system or\npublic land requires approval from Council under Section 68 of the Local Government Act\n1993. Detailed design drawings prepared in accordance with Council's Development Control\nPlan 2005, Chapter 67 - Engineering Requirements for Development must be approved by\nCouncil prior to the issue of a Construction Certificate. All other stormwater management\nworks must be approved by the Accredited Certifier.\nStructural Design Requirements","stage":"before_cc","stage_basis":"heading","page":9},{"label":"19","code":null,"number":"19","title":"","text":"Prior to the issue of a Construction Certificate , the final drawings are to be submitted to the\nMine Subsidence Board for approval and are to include a certification by a qualified structural\nengineer, to the effect that any improvements, constructed to meet the specifications of such\nfinal drawings, will be safe, serviceable and repairable, taking into account the following mine\nsubsidence parameters:\n(a) Maximum vertical subsidence of 150mm.\n(b) Maximum ground strains of +\n1 mm/m.\n(c) maximum tilt of 2 mm/m.","stage":"before_cc","stage_basis":"heading","page":9},{"label":"20","code":null,"number":"20","title":"","text":"Architectural plans submitted to the Mine Subsid ence Board for approval must show the\nlocation and detailing of articulation/control joints in brickwork, taking into consideration the\nsubsidence parameters listed in condition 18 and the requirements of the Building Code of\nAustralia.\nVehicle Access and Parking - Design Requirements","stage":"before_cc","stage_basis":"heading","page":9},{"label":"21","code":null,"number":"21","title":"","text":"The submission of road signage and pavement mark ing design drawings identifying parking\nrestrictions, accesses and traffic management facilities for the internal access roads and\ncarparking area. This shall be submitted to Council for approval by the Local Traffic\nCommittee prior to issue of the Construction Certificate.","stage":"before_cc","stage_basis":"heading","page":9},{"label":"22","code":null,"number":"22","title":"","text":"The submission of a detailed internal traffic ma nagement plan by a suitable qualified traffic\nengineer for the development. The detailed internal traffic management plan shall be\napproved by the Accredited Certifier and shall include but not be limited to:-\n• Parking restrictions, signage, pavement markings a nd traffic management facilities\nfor the access roads and both the southern (rear) and northern (front) carpaking\nareas.\n• Separation of the southern drop off area from thro ugh traffic on the access road with\nmedian island construction, signage and linemarking generally as identified on the\nplan by Martin O’Toole Architects No08-225 sheet B1 C as amended in red. The\ndrop off area shall be identified as one way south to north.\n• The northern (front) accesses and carparking shall be identified as one way east to\nwest. The exit road from the front carpark shall be back to village way by the\nshortest route considering existing trees and shall not connect to the existing\nroundabout to the west.\n• Appropriate signage and linemarking for the direct ion of visitors and service vehicles\nto the various areas of the proposed development.\n• The speed limit on the internal access roads and p roposed traffic calming facilities\nin accordance with AS/NZS2890.1\n• Pedestrian management plan indicating pedestrian d esire lines, pathway provisions\nsafe road crossing provisions and restrictions.","stage":"before_cc","stage_basis":"heading","page":9},{"label":"23","code":null,"number":"23","title":"","text":"The submission to the Accredited Certifier of a detailed car parking and access design. The\ndesign shall include:\n• Minimum width of the circulating roadways shall be in accordance with AS/NZS2890.2\nTable 3.1 for the largest expected design vehicle to access the site.\n• Entry to and exit from the site shall be in a forw ard direction for all vehicles.\n• Access to the service bay areas shall comply with AS/NZS2890.2 Section 4.3\nincluding the requirements of 4.3.1 (a) for the largest expected design vehicle to\naccess each loading bay.\n• Pavement marking and signage in accordance with AS /NZS2890.1/2.\n• Car spaces classified as user class 3 in accordanc e with AS/NZS2890.1.The design of\nall carparking spaces and aisles shall be in accordance with this user class or as\nadjusted in accordance with AS/NZS2890.1 Section 2.4.2 - Angle Parking Aisle.\n• The entire front (northern) carparking module / ar ea, including area required for aisles\nand manoeuvring, shall be contained within the development site boundaries.\n• The carpark to the front (north) of the developmen t entry shall be identified for visitor\ncarparking only.\n• The drop off areas to the front (North) of the dev elopment and rear (south) of the\ndevelopment shall be identified with appropriate signage and pavement marking.\n• The proposed ambulance bay to the front (northern) carparking area shall not impact\non any car spaces entry and exit.\n• The design of all parallel carparking spaces in ac cordance with AS/NZS2890.1\n• Parallel parking spaces shall be identified as sta ff parking only.\n• Disabled car spaces in accordance with AS/NZS 2890 .6.\n• Wheel stops on all carparking spaces.\n• Footpaving and kerb and gutter works shall comply with Development Control Plan\n2005 Chapter 67 - Engineering Requirements for Deve lopments and AS1428.\n• Pavement design to cater for the largest expected design vehicle and axle loadings\n• Minimum pavement surface of asphaltic concrete.\n• Traffic control devices shall be provided as per A S/NZS 2890.1\n• Wheel stops will be required on all angled parking spaces.\n• Connection to Village Way shall be via approved ac cess crossings.\nThe design drawings shall be prepared in accordance with the requirements of AS/NZS 2890\n- Parts 1, 2 and 6, and be approved by the Accredit ed Certifier prior to the issue of a\nConstruction Certificate.","stage":"before_cc","stage_basis":"heading","page":10},{"label":"24","code":null,"number":"24","title":"","text":"The submission to the Accredited Certifier of li ghting design drawings for the carpark, access\nroads and public places. The design shall be prepared in accordance with the requirements\nof AS/NZS 1158 and AS 4282-1997, including the provision of current best practice energy\nefficient lighting and be approved by the Accredited Certifier prior to issue of a Construction\nCertificate.\nWater and Sewer Services - Design Requirements","stage":"before_cc","stage_basis":"heading","page":10},{"label":"25","code":null,"number":"25","title":"","text":"All water and sewer works or works impacting on water and sewer assets must be designed\nand constructed to the requirements of Council as the Water Supply Authority. The\nrequirements are detailed in the Section 306 Notice of Requirements letter attached to this\nconsent. Note: The Section 306 Notice contains requirements associated with the\ndevelopment that must be completed prior to the issue of the Construction Certificate.\nPrior to Commencement of Works:\nThe following conditions must be satisfied prior to the commencement of site works,\nincluding any works relating to demolition, excavation or vegetation removal.\nEcology/Trees Requirements","stage":"before_cc","stage_basis":"heading","page":10},{"label":"26","code":null,"number":"26","title":"","text":"Prior to commencement of works and for the durat ion of the development appropriate actions\nare to be put in place to ensure compliance with the recommendations of the Flora and\nFauna Assessment prepared by Travers Bushfire and Ecology dated July 2011 Reference\nNo A10008F2 and the implementation of the Vegetation Management Plan prepared by\nTravers Bushfire and Ecology dated 28 July 2011 Reference No A10008V.","stage":"before_cc","stage_basis":"heading","page":11},{"label":"27","code":null,"number":"27","title":"","text":"Prior to works associated with the development c ommencing and for the duration of\nconstruction works, the following protocols are to be implemented to ensure tree and\nvegetation protection upon the development site:\n• The EEC restoration area shall be established with seeds from EEC species taken from\nthe site and appropriate endemic tube stock, with details approved by Council. Planting\nis to occur prior to the commencement of building works.\n• Trees and vegetation to be protected by the erecti on of 1.8 metre-high chain wire\ninterlocking fencing as per the engaged Arborist and/or Ecologist’s direction, AS/NZS\n4970-2009 - Protection of Trees on Development Sites and Development Control Plan\n2005, Chapter 67 - Engineering Requirements for Development .\n• Erection of tree protection measures is to be conf irmed to Council’s Development\nEcologist in writing by the Arborist and/or Ecologist prior to commencement of works, or\nalternatively Council must be notified to undertake an inspection of the works.\n• All fenced tree protection areas and are to be cle arly marked as \"No Go Area\" on the\nfencing itself.\n• No clearing of vegetation or storage of vehicles o r machinery, waste, fill or materials or\nunauthorised access is to occur within the fenced tree protection areas.\n• The Arborist and/or Ecologist may require other ha bitat and/or trees to be protected via\nfencing from time to time. This fencing is to be erected at the appropriate root zone\nprotection limits (as determined by the Arborist and/or Ecologist), prior to works being\ncarried out around that particular habitat or tree.\n• The management protocols and requirements within t hese conditions relating to tree and\nvegetation retention, protection and rehabilitation are to be included in all contract\ndocumentation, plans and specifications used by each civil contractor and sub-\ncontractors.\n• The Ecologist and Arborist are to induct each civi l contractor and sub-contractor in\nrelation to the importance of these ecological protocols as part of their site induction\nprogram prior to commencement of works. Certification of this induction must be\nprovided to Council prior to commencement of works.","stage":"before_cc","stage_basis":"heading","page":11},{"label":"28","code":null,"number":"28","title":"","text":"Prior to works associated with the development c ommencing, all trees nominated for\nretention are to be suitably protected by fencing or other accepted protection method in\naccordance with AS/NZS 4970-2009 - Protection of Trees on Development Sites and\nCouncil's Development Control Plan 2005, Chapter 67 - Engineering Requirements for\nDevelopment . All required tree protection measures are to be maintained for the duration of\nconstruction works.","stage":"before_cc","stage_basis":"heading","page":12},{"label":"29","code":null,"number":"29","title":"","text":"Prior to works associated with the development c ommencing, all street trees are to be\nprotected by the installation of a protective fence to the canopy perimeter. Any street tree\ndamaged during building works must be replaced, at no cost to Council, with a tree of similar\nheight and species. Note: The driveway and associated footpath crossing is to be located\nclear of the street trees.\nErosion and Sediment Control Requirements","stage":"before_cc","stage_basis":"heading","page":12},{"label":"30","code":null,"number":"30","title":"","text":"Prior to works associated with the development c ommencing, soil erosion and sediment\ncontrols measures are to be provided on the development site in accordance with Council's\nPolicy E1 - Erosion and Sediment Control from Building Sites and Development Control Plan\n2005, Chapter 67 - Engineering Requirements for Development and the approved\ndevelopment plans.","stage":"before_cc","stage_basis":"heading","page":12},{"label":"31","code":null,"number":"31","title":"","text":"Prior to works associated with the development c ommencing, an appropriate sign to promote\nthe awareness and importance of the maintenance of on-site sediment control techniques is\nto be provided on the most prominent sediment fence or erosion control device within the\ndevelopment site, for the duration of the project.\nFilling and Haulage Requirements","stage":"before_cc","stage_basis":"heading","page":12},{"label":"32","code":null,"number":"32","title":"","text":"Prior to works associated with the development c ommencing, details for the disposal of any\nspoil gained from the site and/or details of the source of fill materials to be imported to the\nsite, are to be provided and approved by the Principal Certifying Authority.\nRoads - Preconstruction Requirements","stage":"before_cc","stage_basis":"heading","page":12},{"label":"33","code":null,"number":"33","title":"","text":"Prior to commencing any works upon public roads the developer will be required to:\n• Obtain a copy of the Council approved Civil Works plans and pavement design (if\napplicable).\n• Obtain a copy of Development Control Plan 2005, Ch apter 67 - Engineering\nRequirements for Development . This is Council’s Specification for Civil Works and is\navailable on Council’s web site.\n• Arrange a meeting on-site with Council’s Principal Development Construction Engineer\non (02) 4350 5555.","stage":"before_cc","stage_basis":"heading","page":12},{"label":"34","code":null,"number":"34","title":"","text":"Prior to works associated with the development c ommencing, a Plan of Management is to be\nsubmitted to and approved by Council as the Roads Authority for any works or deliveries that\nimpact on any public roads or public land as a result of the construction of the development.\nThe plan must include a Traffic Control Plan prepared by a person holding Roads and\nMaritime Authority (RMS) accreditation for selecting and modifying traffic control plans. Fees\nand charges are applicable to the review and approval of the required management plan in\naccordance with Council’s Plan of Management.","stage":"before_cc","stage_basis":"heading","page":12},{"label":"35","code":null,"number":"35","title":"","text":"The submission of a plan of management for any w orks for the development that impact on\nexisting internal road related or carpark areas or areas used by the public / retirement village\ncommunity for the construction phase of the development, prior to that section of work\ncommencing. The plan is to include a Traffic Control Plan and/or a Work Method Statement\nfor any works or deliveries that impact the normal internal travel paths of vehicles,\npedestrians or cyclists or where any materials are lifted over areas used by the public. The\nsafety of the public, residents and staff shall be addressed. This plan must be certified by an\nappropriately accredited/qualified person.","stage":"before_cc","stage_basis":"heading","page":13},{"label":"36","code":null,"number":"36","title":"","text":"Prior to works associated with development comme ncing, a dilapidation report must be\nprepared and submitted to Council as the Roads Authority. The required dilapidation report\nmust document and provide photographs that clearly depict any existing damage to the road,\nkerb, gutter, footpath, driveways, water supply, sewer works, street trees, street signs or any\nother Council assets in the vicinity of the development. Note: The report will be used by\nCouncil to determine the extent of damage arising from site and construction works.\nSite Requirements","stage":"before_cc","stage_basis":"heading","page":13},{"label":"37","code":null,"number":"37","title":"","text":"Prior to works associated with the development c ommencing, the Principal Contractor (or\nOwner/Builder) is to erect a suitable sign in a prominent position on the development site (not\nattached to any tree) identifying the name, address and telephone number of the Principal\nCertifying Authority (PCA) for the work, the name, address and telephone number (including\na number for outside of business hours) of the Principal Contractor for the work (or\nOwner/Builder) and stating that unauthorised entry to the site is prohibited. The required\nsign is to be maintained for the duration of works associated with the development.\nAppropriate signs can be collected from Council’s Customer Service Centre, where Council\nis the nominated Principal Certifying Authority with respect to the development.","stage":"before_cc","stage_basis":"heading","page":13},{"label":"38","code":null,"number":"38","title":"","text":"Prior to works associated with the development c ommencing, suitable toilet facilities must be\navailable or be provided upon the development site, with the required toilet facility(s)\nmaintained until development works are completed at a ratio of one (1) toilet plus one (1)\nadditional toilet for every twenty (20) persons employed at the site. Each toilet must:\n• be a standard flushing toilet connected to a publi c sewer system; or\n• have an on-site effluent disposal system approved under the Local Government Act\n1993, or be a temporary chemical closet approved under the Local Government Act\n1993, supplied by a suitably licensed contractor.","stage":"before_cc","stage_basis":"heading","page":13},{"label":"39","code":null,"number":"39","title":"","text":"Prior to works associated with the development c ommencing, a suitable hoarding or safety\nfence between the work site and the public place is to be provided in accordance with Work\nCover Authority requirements. The required hoarding/fencing is to remain in place during the\nconstruction phase of the development. Should the hoarding/fencing be required to be\nprovided within the road reserve area, approval from Council under the Roads Act as the\nRoads Authority is required to be obtained prior to its erection.\nDuring Construction Works:\nThe following conditions must be satisfied during construction works.\nAcid Sulphate Soils - Construction Requirements","stage":"before_cc","stage_basis":"heading","page":13},{"label":"40","code":null,"number":"40","title":"","text":"Upon completion of excavation works, documentary evidence is to be provided for the\napproval of the Principal Certifying Authority demonstrating compliance with the\nrequirements of the Acid Sulphate Soils Management Plan submitted with respect to the\ndevelopment as prepared by Barker Harle Consulting Engineers and dated 23 July 2011\nReference No 90215.\nApproved Plans","stage":"before_cc","stage_basis":"heading","page":13},{"label":"41","code":null,"number":"41","title":"","text":"A copy of the stamped approved plans must be kep t on site for the duration of site works and\nbe made available upon request to either the Principal Certifying Authority or an officer of the\nCouncil.\nDust Control Requirements","stage":"before_cc","stage_basis":"heading","page":14},{"label":"42","code":null,"number":"42","title":"","text":"Suitable dust suppression measures shall be impl emented and maintained by the developer\nduring demolition, excavation and construction works associated with the development.\nSuch measures are required to minimise the emission of dust and other impurities into the\nsurrounding environment.\nEarthworks and Haulage - Construction Requirements","stage":"before_cc","stage_basis":"heading","page":14},{"label":"43","code":null,"number":"43","title":"","text":"During construction works, all fill is to be pla ced on site in such a manner that surface water\nwill not be permanently or temporarily diverted to adjoining land.\nEcology/Trees - Construction Requirements","stage":"before_cc","stage_basis":"heading","page":14},{"label":"44","code":null,"number":"44","title":"","text":"No tree (or other vegetation) other than those s pecifically notated on the approved plan(s) as\n“tree to be removed’ shall be felled, lopped, topped, ring-barked, uprooted, or otherwise\nwilfully destroyed or removed, without the further written consent of the Consent Authority.","stage":"before_cc","stage_basis":"heading","page":14},{"label":"45","code":null,"number":"45","title":"","text":"Council is to be notified as soon as practicable (and not more than twenty-four (24) hours\nafter) if a breach of these ecological protection conditions occurs.","stage":"before_cc","stage_basis":"heading","page":14},{"label":"46","code":null,"number":"46","title":"","text":"Any approved excavation or filling within a reta ined tree's canopy perimeter shall be in\naccordance with AS/NZS 4970-2009 - Protection of Trees on Development Sites and\nDevelopment Control Plan 2005, Chapter 67 - Engineering Requirements for Development ,\nas excavation or filling can lead to tree instability or death.","stage":"before_cc","stage_basis":"heading","page":14},{"label":"47","code":null,"number":"47","title":"","text":"All services, including water and electricity, m ust be located, designed and installed to\nminimise or prevent root damage to retained trees. Methods for the installation of services\nwithin the tree's canopy perimeter are contained within AS/NZS 4970-2009 - Protection of\nTrees on Development Sites and Development Control Plan 2005, Chapter 67 - Engineering\nRequirements for Development.","stage":"before_cc","stage_basis":"heading","page":14},{"label":"48","code":null,"number":"48","title":"","text":"If canopy thinning is required to achieve Bushfi re Asset Protection Zone then it shall be\nconducted selectively. Those trees with poor health shall be removed prior to those of with\ngood health. Selective removal shall also consider maintenance of species diversity. No\nhollow-bearing trees may be removed to achieve Bushfire Asset Protection Zones. An\nappropriately qualified Arborist or Ecologist and Bushfire Manager are to be engaged to flag\nand clearly identify those trees best removed to achieve bushfire asset protection\nrequirements. Trees must be removed in such a manner so as to prevent damage to\nsurrounding trees to be retained.\nErosion and Sediment Control - Construction Requirements","stage":"before_cc","stage_basis":"heading","page":14},{"label":"49","code":null,"number":"49","title":"","text":"Sand and other materials associated with the con struction of the development that could\npotentially be washed off the site during rain periods, are to be stored behind a suitable\nsediment control barrier.","stage":"before_cc","stage_basis":"heading","page":15},{"label":"50","code":null,"number":"50","title":"","text":"All sediment and erosion control devices provide d with respect to the development are to be\nperiodically cleaned and maintained in an effective state for the duration of works. On the\nspot fines for non-compliance with this requirement may be issued under the provisions of\nthe Protection of Environment Operations Act, 2000 .\nPlumbing and Drainage - Construction Requirements","stage":"before_cc","stage_basis":"heading","page":15},{"label":"51","code":null,"number":"51","title":"","text":"Council as the Water Supply Authority, under the provisions of the Water Management Act,\nor in unsewered areas where an onsite sewage management facility is to be installed, is to\nbe notified to undertake inspections of the internal drainage lines, (prior to the pouring of the\nconcrete slab), and external drainage lines inclusive of sewer junction connection, prior to the\nbackfilling of the trenches. These inspections can be arranged by telephoning Council’s\nCustomer Contact Centre on (02) 4350 5555 a minimum of twenty-four (24) hours prior to the\nrequired time for the inspection. Please note that all drainage inspection fees are to be paid\nto Council prior to plumbing and drainage works associated with the development\ncommencing.\nServices/Utility Requirements","stage":"before_cc","stage_basis":"heading","page":15},{"label":"52","code":null,"number":"52","title":"","text":"The developer is solely responsible for any cost s relating to alterations and extensions of\nexisting roads, drainage, water and sewer infrastructure and other utilities for the proposed\ndevelopment.","stage":"before_cc","stage_basis":"heading","page":15},{"label":"53","code":null,"number":"53","title":"","text":"Other public authorities may have separate requi rements and should be consulted prior to\ncommencement of works in the following respects:\n• Australia Post for the positioning and dimensions of mail boxes in new commercial and\nresidential developments;\n• AGL Sydney Limited for any change or alteration to gas line infrastructure;\n• Ausgrid for any change or alteration to electricit y infrastructure or encroachment within\ntransmission line easements;\n• Telstra, Optus or other telecommunication carriers for access to their\ntelecommunications infrastructure.\nSite Requirements","stage":"before_cc","stage_basis":"heading","page":15},{"label":"54","code":null,"number":"54","title":"","text":"Construction or demolition works involved with t he development may only be carried out\nbetween the hours of 7.00 am and 5.00 pm Monday to Saturday with no construction or\ndemolition works associated with the development permitted to be carried out at any time on\na Sunday or a public holiday.","stage":"before_cc","stage_basis":"heading","page":15},{"label":"55","code":null,"number":"55","title":"","text":"During the construction phase of the development , all building materials, plant and\nequipment must be placed on the site of the development in order to ensure that pedestrian\nand vehicular access within adjoining public roads, footpaths and reserve areas, is not\nrestricted and to prevent damage to public infrastructure.","stage":"before_cc","stage_basis":"heading","page":16},{"label":"56","code":null,"number":"56","title":"The submission of a Construction and Environment Management Plan (CEMP) to the","text":"Principal Certifying Authority for approval prior to the commencement of works. The plan\nmust outline the sequence and construction methodology, and specify mitigating measures\nto ensure all works are carried out with minimal environmental impact in relation to project\nstaging, waste management, traffic management and environmental management.\nWaste Management Requirements","stage":"before_cc","stage_basis":"heading","page":16},{"label":"57","code":null,"number":"57","title":"","text":"During the construction phase of the development , all building materials must be re-used,\nrecycled or disposed of in accordance with the Waste Management Plan submitted with the\nsubject application.\nPrior to Release of Occupation Certificate:\nThe following conditions must be satisfied prior to the release of an Occupation /\nSubdivision Certificate.\nBuilding Code of Australia - Compliance Requirement s","stage":"before_cc","stage_basis":"heading","page":16},{"label":"58","code":null,"number":"58","title":"","text":"Prior to the issue of the Occupation Certificate , the building shall be completed in accordance\nwith the relevant provisions and requirements of the Building Code of Australia.\nBush Fire - Compliance Requirements","stage":"before_cc","stage_basis":"heading","page":16},{"label":"59","code":null,"number":"59","title":"","text":"Prior to the issue of an Occupation Certificate, the proposed new building shall comply with\nsection 5 (BAL 12.5) Australian Standard AS3959-2009 'Construction of buildings in bush\nfire-prone areas' and section A3.7 Addendum Appendix 3 of 'Planning for Bush Fire\nProtection'.","stage":"before_cc","stage_basis":"heading","page":16},{"label":"60","code":null,"number":"60","title":"","text":"Prior to the issue of an Occupation Certificate, water, electricity and gas services are to\ncomply with sections 4.1.3 and 4.2.7 of 'Planning for Bush Fire Protection 2006'.","stage":"before_cc","stage_basis":"heading","page":16},{"label":"61","code":null,"number":"61","title":"","text":"Prior to the issue of an Occupation Certificate, the existing emergency and evacuation\nplanning for the site shall be amended to include the new additions and shall comply with\nsection 4.2.7 of 'Planning for Bush Fire Protection 2006'.","stage":"before_cc","stage_basis":"heading","page":16},{"label":"62","code":null,"number":"62","title":"","text":"Prior to the issue of an Occupation Certificate, landscaping within the site shall comply with\nthe principles of Appendix 5 of 'Planning for Bush Fire Protection 2006'.\nConsolidation","stage":"before_cc","stage_basis":"heading","page":16},{"label":"63","code":null,"number":"63","title":"","text":"The consolidation of Lot 496 DP 755266, Lot 600 DP 728966 and Lot 602 DP 728967 into\none lot by registered subdivision prior to the issue of an Occupation Certificate.\nDocumentary evidence of the Consolidation Plan registration with the Land and Property\nManagement Authority must be submitted to the Accredited Certifier prior to the issue of the\nOccupation Certificate.\nDilapidation Rectification Requirements","stage":"before_cc","stage_basis":"heading","page":17},{"label":"64","code":null,"number":"64","title":"","text":"Prior to the issue of an Occupation Certificate, any damage not shown in the Dilapidation\nReport submitted to and approved by the Principal Certifying Authority prior to site works\ncommencing, will be assumed to have been caused as a result of the site works undertaken\nwith respect to the development and must be rectified at the applicant’s expense.\nDisabled Access Requirements","stage":"before_cc","stage_basis":"heading","page":17},{"label":"65","code":null,"number":"65","title":"","text":"Prior to the issue of an Occupation Certificate, access to and throughout the buildings to be\ncertified by a qualified competent experienced person as comply with AS 1428.1-2009 and\nthe objectives of the Disability Discrimination Act 1992 (Commonwealth).\nEcology/Tree Requirements","stage":"before_cc","stage_basis":"heading","page":17},{"label":"66","code":null,"number":"66","title":"","text":"Prior to the issues of an Occupation Certificate evidence of compliance with the\nrecommendations and actions of the Flora and Fauna Assessment prepared by Travers\nBushfire and Ecology dated July 2011, Reference No A10008F2 and the implementation of\nthe Vegetation Management Plan prepared by Travers Bushfire and Ecology dated 28 July\n2011, Reference No A10008V, is to be submitted to Council.","stage":"before_cc","stage_basis":"heading","page":17},{"label":"67","code":null,"number":"67","title":"","text":"Prior to the issue of an Occupation Certificate, a final certification report detailing the level of\ncompliance for each stage of the development with all conditions relating to ecology/trees\nmust be prepared by the engaged Ecologist and Arborist and forwarded to Council for\nreview.\nExternal Colours/Finishes Requirements","stage":"before_cc","stage_basis":"heading","page":17},{"label":"68","code":null,"number":"68","title":"","text":"Prior to the issue of an Occupation Certificate, the completed development must comply with\nthe schedule of external colours and materials submitted with the application and as shown\non the materials board.\nFilling and Haulage- Completion Requirements","stage":"before_cc","stage_basis":"heading","page":17},{"label":"69","code":null,"number":"69","title":"","text":"All cut/filled areas are to be compacted in acco rdance with the requirements of AS 3798-\n2007. The submission of test results and appropriate documentation attesting to this\nrequirement having been achieved is to be provided for the approval of the Accredited\nCertifier prior to issue of the Occupation Certificate.\nLandscaping Requirements","stage":"before_cc","stage_basis":"heading","page":17},{"label":"70","code":null,"number":"70","title":"","text":"Prior to the issue of an Occupation Certificate , landscaping is to be provided to the\ndevelopment site in accordance with Council's Polic y Number L1 for a Category 3\ndevelopment generally in accordance with the approv ed landscape plan referred to in\nCondition 10 of this consent. Required landscaping is to be the subject of an appropriate\nlandscape implementation report from the approved l andscape consultant submitted to and\napproved by the Principal Certifying Authority.\nLighting Requirements","stage":"before_cc","stage_basis":"heading","page":18},{"label":"71","code":null,"number":"71","title":"","text":"Prior to the issue of an Occupation Certificate, suitable lighting to the proposed carparking\nareas and access roads shall be certified in accordance with the requirements of AS/NZS\n1158, AS 4282-1997 and AS/NZS 2890.\nOther Authorities - Compliance Requirements","stage":"before_cc","stage_basis":"heading","page":18},{"label":"72","code":null,"number":"72","title":"","text":"Compliance with the general terms of approval of the Mine Subsidence Board dated 6\nOctober 2011 and the Rural Fire Service as outlined in its correspondence dated 28\nSeptember 2011.","stage":"before_cc","stage_basis":"heading","page":18},{"label":"73","code":null,"number":"73","title":"","text":"Prior to the issue of an Occupation Certificate, the developer must comply with the\nrequirements (including financial costs) of any relevant utility provider ( for electricity, water,\nsewer, drainage, gas, telecommunications, roads, etc) in relation to any connections,\nworks, repairs, relocation, replacements and/or adjustments to public infrastructure or\nservices affected by the development.\nPlumbing and Drainage - Compliance Requirements","stage":"before_cc","stage_basis":"heading","page":18},{"label":"74","code":null,"number":"74","title":"","text":"Prior to the issue of an Occupation Certificate, rainwater tanks of at least 60,000, litre\ncapacity shall be provided in accordance with the requirements the National Plumbing and\nDrainage Code AS/NZS 3500. The rainwater tanks must be located in such a position as to\nmaximise rainwater collection and shall include, but not be limited to, the retention of water\non-site incorporating first flow diversion devices fixed to all inflows, provided with a\nfunctioning pressure pump, and plumbed to service all toilets and external uses. The tank\nmust be controlled such that supplemental flows from domestic mains do not take place\nuntil the tank is at least 80% empty.\nRoads - Compliance Requirements","stage":"before_cc","stage_basis":"heading","page":18},{"label":"75","code":null,"number":"75","title":"","text":"All road signage and pavement marking works must be completed in accordance with the\nplans approved by the Local Traffic Committee and approved by Council as the Roads\nAuthority prior to the issue of any Occupation Certificate.","stage":"before_cc","stage_basis":"heading","page":18},{"label":"76","code":null,"number":"76","title":"","text":"The provision of any additional civil works requ ired to ensure satisfactory transitions to\nexisting work as a result of work conditioned for the development works are to be approved\nby Council as the Roads Authority prior to issue of the Occupation Certificate.","stage":"before_cc","stage_basis":"heading","page":18},{"label":"77","code":null,"number":"77","title":"","text":"All works within the public road must be complet ed in accordance with the approved Civil\nWorks design drawings and Development Control Plan 2005, Chapter 67 - Engineering\nRequirements for Development and be approved by Council as the Roads Authority prior to\nthe issue of any Occupation Certificate.\n77A All works associated with the development or r equired by conditions of consent are to be\nundertaken by the Developer at no cost to Council.","stage":"before_cc","stage_basis":"heading","page":18},{"label":"78","code":null,"number":"78","title":"","text":"The submission to the Council as the Roads Autho rity of certification from an Accredited\nService Provider (ASP) that the street lighting installation has been completed in\naccordance with AS/NZS 1158 and AS 4282-1997, the approved design drawings and will\nachieve a minimum of twenty (20) year design life. The certification must be received by\nCouncil prior to the issue of the Occupation Certificate.\nStormwater - Compliance Requirements","stage":"before_cc","stage_basis":"heading","page":19},{"label":"79","code":null,"number":"79","title":"","text":"The construction of the stormwater management sy stem in accordance with the approved\nStormwater Management Plan and AS/NZS 3500.3-2004. Certification of the construction\nby a suitably qualified consultant shall be provided to the Principal Certifying Authority prior\nto issue of the Occupation Certificate.","stage":"before_cc","stage_basis":"heading","page":19},{"label":"80","code":null,"number":"80","title":"","text":"The construction of stormwater drainage works ex ternal to the site and discharging into a\npublic system or public land in accordance with the approved Stormwater Management\nPlan and Development Control Plan 2005, Chapter 67 - Engineering Requirements for\nDevelopment . All works must be approved by Council under Section 68 of the Local\nGovernment Act 1993 prior to issue of the Occupation Certificate. All other stormwater\nmanagement works must be approved by the Principal Certifying Authority.\nVehicle Access and Parking - Compliance Requirement s","stage":"before_cc","stage_basis":"heading","page":19},{"label":"81","code":null,"number":"81","title":"","text":"The provision of all works and activities associ ated with the detailed traffic management\nplan, the approved plans, AS/NZS 2890 - Parts 1/2/6 and these conditions of consent.\nCertification by a suitably qualified consultant shall be provided to the Principal Certifying\nAuthority prior to issue of the Occupation Certificate.\nWaste Management Requirements","stage":"before_cc","stage_basis":"heading","page":19},{"label":"82","code":null,"number":"82","title":"","text":"For safety, amenity and maintenance reasons, the waste storage area must be constructed\nto the following standards prior to the issue of an Occupation Certificate:\n• Floors must be constructed of concrete, graded and drained to an approved drainage\noutlet connected to the sewer and finished to a smooth even trowelled surface;\n• Walls must be constructed with solid impervious ma terial and shall be cement rendered\ninternally to a smooth even steel trowelled surface;\n• All intersections between the walls and floors sha ll be coved with coving having a\nminimum radius of 25mm;\n• All entry points into the room must be bunded to p revent the escape of liquid waste.\nBunding shall be for 110% of the likely liquid storage waste and constructed in such a\nmanner that does not obstruct the removal of waste receptacles from the room or create\na safety risk to users;\n• Adequate ventilation shall be provided;\n• Adequate lighting shall be provided;\n• The ceiling must have a minimum height of 2.1 metr es from floor level and be finished\nwith a smooth faced non-absorbent material capable of being easily cleaned;\n• Waste storage areas shall prevent the access of ve rmin;\n• Waste receptacles used shall be compatible with Wy ong Council’s waste collection\nservice;\n• The door to the storage area shall be weatherproof and shall be openable from the inside\nat all times; and\n• Hot and cold water hose cocks shall be located ins ide or within close proximity to the\nwaste storage areas to facilitate cleaning.\nWater and Sewer Services/Infrastructure - Complianc e Requirements","stage":"before_cc","stage_basis":"heading","page":19},{"label":"83","code":null,"number":"83","title":"","text":"The obtaining of a Section 307 Certificate of Co mpliance under the Water Management Act\n2000 for water and sewer requirements for the development from Wyong Shire Council as\nthe Water Supply Authority prior to issue of the Occupation Certificate. All works for the\ndevelopment must be approved by Council prior to the issue of a Certificate of Compliance.\nWork as Executed Requirements\n84 rior to the issue of an Occupation Certificate, Works as Executed information for the\ndevelopment as identified in Council's Development Control Plan 2005, Chapter 67 -\nEngineering Requirements for Development is to be submitted to and approved by Council.\nThe required Works as Executed information is to be submitted in hard copy and in\nelectronic format in accordance with Council’s ‘CADCHECK’ requirements.\nOngoing Operation:\nThe following conditions must be satisfied during use / occupation of the development.\nBush Fire Compliance Requirements","stage":"before_cc","stage_basis":"heading","page":20},{"label":"85","code":null,"number":"85","title":"","text":"The 20 metre asset protection zones on the adjoi ning Crown Reserves are to remain in\nplace and must be fuel managed so as to maintain fuel loadings as detailed within Planning\nfor Bushfire Protection Guidelines 2006 (NSW).","stage":"before_cc","stage_basis":"heading","page":20},{"label":"86","code":null,"number":"86","title":"","text":"The buildings and the site shall be managed for the life of the development in accordance\nwith the recommendations made in the Bushfire Hazard Assessment Report, prepared by\nBuilding Code & Bushfire Hazard Solutions Pty Limited dated 26 July 2011 and submitted\nwith the development application and the Bushfire Safety Authority issued by the NSW rural\nFire Service, dated 28 September 2011.\nLighting Spill Requirements","stage":"before_cc","stage_basis":"heading","page":20},{"label":"87","code":null,"number":"87","title":"","text":"All external lighting is to be of a type that mi nimises overspill into retained vegetated areas.\nStormwater - Ongoing Maintenance Requirements","stage":"before_cc","stage_basis":"heading","page":20},{"label":"88","code":null,"number":"88","title":"","text":"All stormwater treatment devices (including drai nage systems, sumps and traps) must be\nregularly maintained in order to remain effective.\nVehicle Access and Parking - Ongoing Requirements","stage":"before_cc","stage_basis":"heading","page":21},{"label":"89","code":null,"number":"89","title":"","text":"Access to and from the site for all commercial v ehicles, including waste collection vehicles\nmust only be from the eastern access road.","stage":"before_cc","stage_basis":"heading","page":21},{"label":"90","code":null,"number":"90","title":"","text":"Garbage/recycling bins must not be permitted to encroach with the carpark or vehicle\nmanoeuvring areas.","stage":"before_cc","stage_basis":"heading","page":21},{"label":"91","code":null,"number":"91","title":"","text":"All on-site vehicle parking areas, markings, dri veways and manoeuvring areas are to be\nmaintained for the life of the development.\nWaste Management - Compliance Requirements","stage":"before_cc","stage_basis":"heading","page":21},{"label":"92","code":null,"number":"92","title":"","text":"All waste generated on the premises shall be tra nsported to a facility which is licensed to\nreceive that material.","stage":"before_cc","stage_basis":"heading","page":21}]});
